/* Which surahs have tadabbur, derived rather than typed — the site
   has been bitten before by a hand-written list going stale while
   the data moved on (the analytics TRACKED_PAGES). */
function iitwTadabburSurahs() {
  return Object.keys(TADABBUR).map(Number).sort(function (a, b) { return a - b; });
}

/* Does this surah have anything, and how much of it. Used by the
   Quran page to decide whether to offer the button at all, and to
   label honestly when only part of a surah is covered. */
function iitwTadabburFor(surahNum) {
  const t = TADABBUR[surahNum];
  if (!t) return null;
  return {
    data: t,
    /* The surah number travels with the data so the panel can say WHICH
       surah and verse each block belongs to. Without it the box opened with
       "Why this verse, and why these words" and never named the verse — a
       reader scrolling a long surah had no anchor for what they were
       looking at, and nothing to quote or search for afterwards. */
    num: surahNum,
    /* Sorted, so the coverage line reads 1, 2, 3, 255 regardless of the
       order entries were added to the array. Without this, appending a
       verse to a surah that already had several printed them out of
       sequence, which looks like a data error to a reader. */
    verses: (t.ayat || []).map(function (a) { return a.n; })
              .sort(function (x, y) { return x - y; }),
    partial: !!t.partial
  };
}
